    [5166] = {l=60,ml=57,s={n="Catalogue of the Wayward",a=28,x=39.4,y=66.6},e={n="Jeziba",a=28,x=39.4,y=66.8},r={5164},o="To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  10 Frayed Abomination Stitchings.",st={{n="Chromatic Carapace",a=1583,m={"Gyth"}},{n="Brilliant Chromatic Scale",a=1583,m={"Chromatic Dragonspawn","Chromatic Elite Guard"}},{n="Blood of Heroes",a=139,x=57.4,y=64},{n="Frayed Abomination Stitching",a=2017,m={"Bile Spewer","Patchwork Horror","Ramstein the Gorger","Venom Belcher"}}}},
    [5167] = {l=60,ml=57,s={n="Catalogue of the Wayward",a=28,x=39.4,y=66.6},e={n="Jeziba",a=28,x=39.4,y=66.8},r={5164},o="To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  5 Skin of Shadow.",st={{n="Chromatic Carapace",a=1583,m={"Gyth"}},{n="Brilliant Chromatic Scale",a=1583,m={"Chromatic Dragonspawn","Chromatic Elite Guard"}},{n="Blood of Heroes",a=139,x=57.4,y=64},{n="Skin of Shadow",a=2057,m={"Instructor Malicia","Lady Illucia Barov","Lorekeeper Polkelt","Risen Bonewarder"}}}},
    [5168] = {l=56,ml=50,s={n="Carlin Redpath",a=139,x=71.7,y=50},e={n="Carlin Redpath",a=139,x=71.7,y=50},r={5210},o="Bring Davil's Libram and Redpath's Shield to Carlin Redpath.",st={{n="Davil's Libram",a=28,x=42.5,y=19},{n="Redpath's Shield",a=28,x=63.8,y=57.2}}},
    [5181] = {l=57,ml=50,s={n="Carlin Redpath",a=139,x=71.7,y=50},e={n="Carlin Redpath",a=139,x=71.7,y=50},r={5210},o="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.",st={{n="Skull of Horgus",a=139,x=44.3,y=41.2},{n="Shattered Sword of Marduk",a=139,x=46.9,y=55.4}}},
    [5206] = {l=60,ml=50,s={n="Carlin Redpath",a=139,x=71.7,y=50},e={n="Carlin Redpath",a=139,x=71.7,y=50},r={5168,5181},o="Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands."},
    [5210] = {l=56,ml=50,s={n="Chromie",a=28,x=39.5,y=66.8},e={n="Carlin Redpath",a=139,x=71.7,y=50},r={5154},o="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."},
    [5241] = {l=56,ml=50,s={n="Pamela Redpath",a=139,x=31.2,y=78},e={n="Carlin Redpath",a=139,x=71.7,y=50},r={5149},o="Find Carlin Redpath."},
    [5243] = {l=60,ml=55,d="strat",s={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},e={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},o="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",st={{n="Stratholme Holy Water",a=2017}}},
    [5382] = {l=60,ml=55,d="scho",s={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},e={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},o="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete. ",st={{n="Doctor Theolen Krastinov",a=2057},{n="Remains of Eva Sarkhoff Burned",a=2057},{n="Remains of Lucien Sarkhoff Burned",a=2057}}},
    [5384] = {l=60,ml=55,d="scho",s={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},e={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},r={5515},o="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff. ",st={{n="Kirtonos the Herald",a=2057}}},
    [5461] = {l=60,ml=57,s={n="Magistrate Marduke",a=28,x=70.6,y=74.1},e={n="Magistrate Marduke",a=28,x=70.6,y=74.1},r={5384},o="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.",st={{n="Keepsake of Remembrance",a=45,x=23.3,y=65.7}}},
    [5462] = {l=60,ml=57,s={n="Magistrate Marduke",a=28,x=70.6,y=74.1},e={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},r={5461},o="Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."},
    [5463] = {l=60,ml=57,d="strat",s={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},e={n="Menethil's Gift",a=2017},r={5462},o="Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."},
    [5464] = {l=60,ml=57,s={n="Menethil's Gift",a=2017},e={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},r={5463},o="Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."},
    [5465] = {l=60,ml=57,s={n="Leonid Barthalomew the Revered",a=139,x=71.9,y=48.3},e={n="Magistrate Marduke",a=28,x=70.6,y=74.1},r={5464},o="Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."},
    [5466] = {l=60,ml=57,d="scho",s={n="Magistrate Marduke",a=28,x=70.6,y=74.1},e={n="Magistrate Marduke",a=28,x=70.6,y=74.1},r={5465},o="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",st={{n="Human Head of Ras Frostwhisper",a=2057,m={"Ras Frostwhisper"}}}},
    [5515] = {l=60,ml=55,d="scho",s={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},e={n="Eva Sarkhoff",a=28,x=70.2,y=73.7},r={5382},o="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",st={{n="Krastinov's Bag of Horrors",a=2057,m={"Jandice Barov"}}}},
    [5526] = {l=60,ml=56,s={n="Rabine Saturna",a=493,x=51.7,y=45.1},e={n="Rabine Saturna",a=493,x=51.7,y=45.1},r={5527},o="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."},
    [5527] = {l=60,ml=56,s={n="Rabine Saturna",a=493,x=51.7,y=45.1},e={n="Rabine Saturna",a=493,x=51.7,y=45.1},o="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.",st={{n="Reliquary of Purity",a=1377,x=63.2,y=55.4}}},
    [5542] = {l=56,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},o="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.",st={{n="Plaguehound Runt",a=139,x=15.7,y=62.4},{n="Plaguehound",a=139,x=51.6,y=50.7},{n="Frenzied Plaguehound",a=139,x=50.4,y=27.1}}},
    [5543] = {l=56,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},o="Slay 30 Plaguebats and return to Tirion Fordring.",st={{n="Plaguebat",a=139,x=19.7,y=61.8}}},
    [5544] = {l=56,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},o="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat. ",st={{n="Slab of Carrion Worm Meat",a=139,x=50.6,y=45.6,m={"Carrion Grub","Carrion Devourer"}}}},
    [5721] = {l=60,ml=55,s={n="Chromie",a=28,x=39.5,y=66.8},e={n="Pamela Redpath",a=139,x=31.2,y=78},r={5941},o="Place the Relic Bundle at the Darrowshire town square.  Prevent Davil Lightfire's death until the death of Horgus.  Prevent Captain Redpath's death until Redpath the Corrupted appears.  Defeat Redpath the Corrupted.  Speak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.",st={{n="Joseph Redpath",a=139,x=33.6,y=78.5}}},
    [5742] = {l=56,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},r={5542,5543,5544},o="Listen to what Tirion Fordring has to say.",st={{n="Tirion Fordring",a=139,x=5.2,y=35.6}}},
    [5781] = {l=57,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},r={5742},o="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.",st={{n="Taelan's Hammer",a=139,x=23.9,y=74.2,m={"Mercutio Filthgorger"}}}},
    [5845] = {l=58,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},r={5781},o="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.",st={{n="Symbol of Lost Honor",a=139,x=62.5,y=26.8}}},
    [5846] = {l=58,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Artist Renfray",a=28,x=65.8,y=75.4},r={5845},o="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
    [5848] = {l=60,ml=52,d="strat",s={n="Artist Renfray",a=28,x=65.8,y=75.4},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},r={5846},o="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.  Return the painting to Tirion Fordring.",st={{n="Of Love and Family",a=2017}}},
    [5861] = {l=60,ml=52,s={n="Tirion Fordring",a=139,x=5.2,y=35.6},e={n="Myranda the Hag",a=28,x=50.8,y=77.9},r={5848},o="Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift."},
    [5862] = {l=60,ml=52,s={n="Myranda the Hag",a=28,x=50.8,y=77.9},e={n="Highlord Taelan Fordring",a=28,x=42,y=14.8},r={5861},o="Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.  Hearthglen is to the north, Taelan should be inside of Mardenholde Keep."},
    [5863] = {l=49,ml=44,s={n="Andi Lynn",a=440,x=52.8,y=27.4},e={n="Andi Lynn",a=440,x=52.8,y=27.4},o="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.",st={{n="Dunemaul Brute",a=440,x=40.8,y=54.9},{n="Dunemaul Enforcer",a=440,x=40.1,y=55.8},{n="Gor'marok the Ravager",a=440,x=41.5,y=57.8}}},
    [5941] = {l=60,ml=50,s={n="Carlin Redpath",a=139,x=71.7,y=50},e={n="Chromie",a=28,x=39.5,y=66.8},r={5206},o="Take the Bundle of Relics to Chromie in Andorhal."},
    [5942] = {l=60,ml=50,s={n="Pamela Redpath",a=139,x=31.2,y=78},e={n="Joseph's Chest",a=139,x=30.9,y=77.8},r={5721},o="Bring Joseph's Key to Joseph's Chest."},
    [5944] = {l=60,ml=52,s={n="Highlord Taelan Fordring",a=28,x=42,y=14.8},e={n="Tirion Fordring",a=139,x=5.2,y=35.6},r={5862},o="Escort Taelan Fordring out of Hearthglen.",st={{n="Redemption?",a=28,x=53.9,y=24.3}}},
    [5961] = {l=56,ml=54,f="Horde",s={n="Lady Sylvanas Windrunner",a=1497,x=58.1,y=91.8},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},o="Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead. "},
    [6022] = {l=58,ml=54,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},o="Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot."},
    [6042] = {l=58,ml=54,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},o="Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.",st={{n="Noxious Plaguebat",a=139,x=49.7,y=50.1},{n="Monstrous Plaguebat",a=139,x=50.2,y=26.5}}},
    [6133] = {l=60,ml=54,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},o="Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.",st={{n="Pathstrider",a=139,x=46.3,y=12.5},{n="Ranger",a=139,x=45.4,y=12.9},{n="Woodsman",a=139,x=45.5,y=12.8},{n="Quel'Thalas Registry",a=139,x=45.3,y=12.7}}},
    [6134] = {l=39,ml=34,s={n="Hornizz Brimbuzzle",a=405,x=47.8,y=61.8},e={n="Hornizz Brimbuzzle",a=405,x=47.8,y=61.8},o="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.",st={{n="Ghost-o-plasm",a=405,x=64.2,y=91.6,m={"Magrami Spectre"}}}},
    [6135] = {l=60,ml=56,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={6022,6042,6133},o="Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.  It is said that Duskwing roams the countryside to the north of Marris Stead.",st={{n="Patch of Duskwing's Fur",a=139,x=26.1,y=59,m={"Duskwing"}}}},
    [6136] = {l=60,ml=56,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={5961,6022,6042,6133},o="Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.",st={{n="Borelgore",a=139,x=47.7,y=24.9}}},
    [6144] = {l=60,ml=56,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Varimathras",a=1497,x=56.3,y=92.2},r={6135,6136},o="Travel to the Undercity and speak with Varimathras."},
    [6145] = {l=60,ml=56,f="Horde",s={n="Varimathras",a=1497,x=56.3,y=92.2},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={6144},o="Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.  Take the command to Nathanos Blightcaller for further instruction.",st={{n="The Grand Crusader's Command",a=139,x=51.4,y=30.6,m={"Crimson Courier"}}}},
    [6146] = {l=60,ml=56,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Crusader Lord Valdelmar",a=139,x=75.2,y=71.2},r={6145},o="Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar."},
    [6147] = {l=60,ml=56,f="Horde",s={n="Crusader Lord Valdelmar",a=139,x=75.2,y=71.2},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={6146},o="Return to Nathanos Blightcaller with the new information. "},
    [6148] = {l=60,ml=56,f="Horde",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={6147},o="The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.",st={{n="Demetria",a=139,x=63.3,y=67.2}}},
    [6163] = {l=60,ml=56,f="Horde",d="strat",s={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},e={n="Nathanos Blightcaller",a=139,x=22.2,y=63.5},r={6135,6136},o="Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",st={{n="Head of Ramstein the Gorger",a=2017,m={"Ramstein the Gorger"}}}},
    [6421] = {l=18,ml=14,f="Horde",s={n="Mor'rogal",a=406,x=47.2,y=64},e={n="Mor'rogal",a=406,x=47.2,y=64},o="Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.",st={{n="Resonite Crystal",a=406,x=59.5,y=91.3},{n="Investigate Cave in Boulderslide Ravine",a=406,x=58.2,y=89.5}}},
    [6481] = {l=20,ml=14,f="Horde",s={n="Mor'rogal",a=406,x=47.2,y=64},e={n="Mor'rogal",a=406,x=47.2,y=64},r={6421},o="Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.",st={{n="Goggeroc",a=406,x=57.4,y=89.4}}},
    [6504] = {l=30,ml=23,f="Horde",s={n="Gurda Ragescar",a=331,x=70,y=71.2},e={n="Gurda Ragescar",a=331,x=70,y=71.2},o="Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post. "},
    [6521] = {l=36,ml=28,f="Horde",s={n="Varimathras",a=1497,x=56.3,y=92.2},e={n="Varimathras",a=1497,x=56.3,y=92.2},r={6522},o="Bring Ambassador Malcin's Head to Varimathras in the Undercity.",st={{n="Ambassador Malcin's Head",a=17,x=48,y=93.5,m={"Ambassador Malcin"}}}},
    [6522] = {l=36,ml=28,f="Horde",s={n="Small Scroll",a=491},e={n="Varimathras",a=1497,x=56.3,y=92.2},o="Take the Small Scroll to Varimathras in the Undercity."},
    [6562] = {l=22,ml=17,f="Horde",s={n="Tsunaman",a=406,x=47.4,y=64.3},e={n="Je'neu Sancrea",a=331,x=11.6,y=34.3},o="Speak to Je'neu Sancrea in Ashenvale."},
    [6564] = {l=22,ml=17,f="Horde",s={n="Damp Note",a=331,x=13.6,y=12.1},e={n="Je'neu Sancrea",a=331,x=11.6,y=34.3},r={6562},o="Bring the Damp Note to Je'neu Sancrea in Ashenvale."},
    [6565] = {l=26,ml=17,f="Horde",d="bfd",s={n="Je'neu Sancrea",a=331,x=11.6,y=34.3},e={n="Je'neu Sancrea",a=331,x=11.6,y=34.3},r={6564},o="Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",st={{n="Lorgus Jett",a=719}}},
    [6566] = {l=60,ml=55,f="Horde",s={n="Thrall",a=1637,x=31.7,y=37.8},e={n="Thrall",a=1637,x=31.7,y=37.8},r={4974},o="Listen to Thrall.",st={{n="Thrall's Tale",a=1637,x=31.8,y=37.8}}},
    [6567] = {l=60,ml=55,f="Horde",s={n="Thrall",a=1637,x=31.7,y=37.8},e={n="Rexxar",a=405,x=54,y=2},r={6566},o="Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas."},
    [6568] = {l=60,ml=55,f="Horde",s={n="Rexxar",a=405,x=54,y=2},e={n="Myranda the Hag",a=28,x=50.8,y=77.9},r={6567},o="Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands."},
    [6569] = {l=60,ml=55,f="Horde",d="lbrs",s={n="Myranda the Hag",a=28,x=50.8,y=77.9},e={n="Myranda the Hag",a=28,x=50.8,y=77.9},r={6568},o="Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.",st={{n="Black Dragonspawn Eye",a=1583,m={"Overlord Wyrmthalak","Rage Talon Captain","Rage Talon Dragon Guard","Rage Talon Dragonspawn"}}}},
    [6570] = {l=60,ml=55,f="Horde",s={n="Myranda the Hag",a=28,x=50.8,y=77.9},e={n="Emberstrife",a=15,x=56.7,y=87.7},r={6569},o="Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife. "},
    [6571] = {l=27,ml=22,f="Horde",s={n="Locke Okarr",a=331,x=71.4,y=67.6},e={n="Locke Okarr",a=331,x=71.4,y=67.6},o="Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.",st={{n="Warsong Saw Blades",a=331,x=73.1,y=61.5,m={"Pixel"}},{n="Warsong Axe Shipment",a=33,x=26.4,y=73.3},{n="Warsong Oil",a=331,x=79.1,y=48},{n="Logging Rope",a=331,x=37.3,y=35.9,m={"Thistlefur Shaman","Thistlefur Avenger","Thistlefur Totemic","Foulweald Warrior"}}}},
    [6582] = {l=60,ml=55,f="Horde",s={n="Emberstrife",a=15,x=56.7,y=87.7},e={n="Emberstrife",a=15,x=56.7,y=87.7},r={6570},o="You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring.",st={{n="The Skull of Scryer",a=618,x=52.7,y=55.9,m={"Scryer"}}}},
    [6583] = {l=60,ml=55,f="Horde",s={n="Emberstrife",a=15,x=56.7,y=87.7},e={n="Emberstrife",a=15,x=56.7,y=87.7},r={6570},o="Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.",st={{n="The Skull of Somnus",a=8,x=76,y=66.6,m={"Somnus"}}}},
    [6584] = {l=60,ml=55,f="Horde",s={n="Emberstrife",a=15,x=56.7,y=87.7},e={n="Emberstrife",a=15,x=56.7,y=87.7},r={6570},o="Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.",st={{n="The Skull of Chronalis",a=440,x=64.2,y=48.5,m={"Chronalis"}}}},
    [6585] = {l=60,ml=55,f="Horde",s={n="Emberstrife",a=15,x=56.7,y=87.7},e={n="Emberstrife",a=15,x=56.7,y=87.7},r={6582,6583,6584},o="Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",st={{n="The Skull of Axtroz",a=11,x=81.8,y=48.2,m={"Axtroz"}}}},
    [6601] = {l=60,ml=55,f="Horde",s={n="Emberstrife",a=15,x=56.7,y=87.7},e={n="Rexxar",a=405,x=54,y=2},r={6585},o="It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."},
    [6602] = {l=60,ml=55,f="Horde",d="lbrs",s={n="Rexxar",a=405,x=54,y=2},e={n="Rexxar",a=405,x=54,y=2},r={6601},o="Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.",st={{n="Blood of the Black Dragon Champion",a=1583,m={"General Drakkisath"}}}},
    [7028] = {l=47,ml=41,d="mara",s={n="Willow",a=405,x=62.2,y=39.6},e={n="Willow",a=405,x=62.2,y=39.6},o="Collect 15 Theradric Crystal Carvings for Willow in Desolace.",st={{n="Theradric Crystal Carving",a=2100,m={"Barbed Lasher","Cavern Lurker","Cavern Shambler","Celebras the Cursed"}}}},
    [7029] = {l=47,ml=41,f="Horde",d="mara",s={n="Vark Battlescar",a=405,x=23.2,y=70.3},e={n="Vark Battlescar",a=405,x=23.2,y=70.3},o="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.",st={{n="Vylestem Vines healed",a=2100},{n="Filled Cerulean Vial",a=405,x=33.2,y=65.7}}},
    [7041] = {l=47,ml=41,f="Alliance",d="mara",s={n="Talendria",a=405,x=68.5,y=8.9},e={n="Talendria",a=405,x=68.5,y=8.9},o="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.",st={{n="Vylestem Vines healed",a=2100},{n="Filled Cerulean Vial",a=405,x=33.2,y=65.7}}},
    [7068] = {l=42,ml=39,f="Horde",s={n="Uthel'nay",a=1637,x=39.2,y=86.3},e={n="Uthel'nay",a=1637,x=39.2,y=86.3},o="Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",st={{n="Shadowshard Fragment",a=405,x=27.8,y=56,m={"Shadowshard Rumbler","Shadowshard Smasher"}}}},
    [7070] = {l=42,ml=39,f="Alliance",s={n="Archmage Tervosh",a=15,x=66.4,y=49.3},e={n="Archmage Tervosh",a=15,x=66.4,y=49.3},o="Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",st={{n="Shadowshard Fragment",a=405,x=27.8,y=56,m={"Shadowshard Rumbler","Shadowshard Smasher"}}}},
    [7201] = {l=54,ml=48,f="Horde",d="brd",s={n="Shadowmage Vivian Lagrave",a=3,x=2.9,y=47.8},e={n="Shadowmage Vivian Lagrave",a=3,x=2.9,y=47.8},r={3906},o="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals. ",st={{n="Essence of the Elements",a=1584,m={"Ambassador Flamelash","Blazing Fireguard","Fireguard","Fireguard Destroyer"}}}},
    [7461] = {l=60,ml=56,d="dm",s={n="Shen'dralar Ancient"},e={n="Shen'dralar Ancient"},o="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete this quest.",st={{n="Immol'thar",a=10025},{n="Prince Tortheldrin",a=10022}}},
    [7462] = {l=60,ml=56,f="Alliance",d="dm",s={n="Shen'dralar Ancient"},e={n="Treasure of the Shen'dralar",a=10022},r={7461},o="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
    [7490] = {l=60,ml=60,f="Horde",s={n="Head of Onyxia",a=2159},e={n="Thrall",a=1637,x=31.7,y=37.8},r={6602},o="Take the Head of Onyxia to Thrall in Orgrimmar."},
