    [7501] = {l=60,ml=54,cl=2,d="dm",s={n="The Light and How to Swing It",a=10022},e={n="Lorekeeper Mykos"},o="Return the book to its rightful owners."},
    [7703] = {l=60,ml=56,d="dm",s={n="Captain Kromcrush"},e={n="Captain Kromcrush"},o="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",st={{n="Gauntlet of Gordok Might",a=10022}}},
    [7849] = {l=50,ml=46,f="Horde",s={n="Huntsman Markhor",a=47,x=79.2,y=79.5},e={n="Huntsman Markhor",a=47,x=79.2,y=79.5},o="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.  Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.",st={{n="Huntsman Malkhor's Skull",a=47,x=58.6,y=64.8},{n="Huntsman Malkhor's Bones",a=47,x=62.1,y=75.4}}},
    [7861] = {l=51,ml=46,f="Horde",s={n="Call to Arms!",a=47,x=79.1,y=79},e={n="Primal Torntusk",a=47,x=78.2,y=81.2},o="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.",st={{n="Vile Priestess Hexx",a=47,x=59.5,y=78.3},{n="Vilebranch Aman'zasi Guard",a=47,x=58,y=82.2}}},
    [7877] = {l=60,ml=56,d="dm",s={n="Shen'dralar Ancient"},e={n="Treasure of the Shen'dralar",a=10022},r={7461},o="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
