    [8182] = {l=58,ml=40,s={n="Prospector Ironboot",a=440,x=66.9,y=24},e={n="Molthor",a=33,x=15,y=15.1},r={8181},o="Speak with Molthor in Stranglethorn."},
    [8251] = {l=52,ml=50,s={n="Archmage Xylem",a=16,x=29.3,y=40.2},e={n="Archmage Xylem",a=16,x=29.3,y=40.2},o="Bring 10 Glittering Dust to Archmage Xylem.",st={{n="Glittering Dust",a=16,x=63.6,y=28.7,m={"Blood Elf Arcanist","Blood Elf Reclaimer","Blood Elf Surveyor"}}}},
    [8252] = {l=52,ml=50,s={n="Archmage Xylem",a=16,x=29.3,y=40.2},e={n="Archmage Xylem",a=16,x=29.3,y=40.2},r={8251},o="Collect 6 Enchanted Coral and return them to Archmage Xylem.",st={{n="Enchanted Coral",a=16,x=43.5,y=56.4,m={"Spitelash Siren"}}}},
    [8253] = {l=52,ml=50,s={n="Archmage Xylem",a=16,x=29.3,y=40.2},e={n="Archmage Xylem",a=16,x=29.3,y=40.2},r={8252},o="Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.",st={{n="Arcane Shard",a=1477,m={"Morphaz"}}}},
    [8254] = {l=52,ml=50,s={n="Malakai Cross",a=1638,x=24.6,y=22.6},e={n="Ogtinc",a=16,x=42.4,y=42.6},o="Seek out Ogtinc in Azshara."},
    [8255] = {l=52,ml=50,s={n="Ogtinc",a=16,x=42.4,y=42.6},e={n="Ogtinc",a=16,x=42.4,y=42.6},r={8254},o="Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",st={{n="Healthy Courser Gland",a=16,x=51.8,y=81,m={"Mosshoof Courser"}}}},
    [8256] = {l=52,ml=50,s={n="Ogtinc",a=16,x=42.4,y=42.6},e={n="Ogtinc",a=16,x=42.4,y=42.6},r={8255},o="Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",st={{n="Ichor of Undeath",a=28,x=43.9,y=64.3,m={"Skeletal Acolyte","Skeletal Flayer","Slavering Ghoul","Searing Ghoul"}}}},
    [8257] = {l=52,ml=50,s={n="Ogtinc",a=16,x=42.4,y=42.6},e={n="Greta Mosshoof",a=361,x=51.2,y=82.1},r={8256},o="Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows.",st={{n="Blood of Morphaz",a=1477,m={"Morphaz"}}}},
    [8273] = {l=47,ml=42,f="Horde",s={n="Oran Snakewrithe",a=1497,x=73.1,y=32.9},e={n="Oran Snakewrithe",a=1497,x=73.1,y=32.9},r={2782}},
    [8304] = {l=60,ml=58,s={n="Commander Mar'alith",a=1377,x=49.2,y=34.2},e={n="Commander Mar'alith",a=1377,x=49.2,y=34.2},o="Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.  Once you have gathered the requested information, return to Commander Mar'alith.",st={{n="Frankal Stonebridge",a=1377,x=40.8,y=88.9},{n="Rutgar Glyphshaper",a=1377,x=41.3,y=88.5}}},
    [8306] = {l=60,ml=58,s={n="Commander Mar'alith",a=1377,x=49.2,y=34.2},e={n="Commander Mar'alith",a=1377,x=49.2,y=34.2},r={8304},o="Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And <Name>, remember the Commander's words: \"Do what you must...\"",st={{n="The Fate of Mistress Natalia Mar'alith",a=10073,x=44.4,y=86.1}}},
    [8309] = {l=60,ml=58,s={n="Rutgar Glyphshaper",a=1377,x=41.3,y=88.5},e={n="Rutgar Glyphshaper",a=1377,x=41.3,y=88.5},r={8304},o="Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.",st={{n="Hive'Ashi Rubbing",a=1377,x=50.9,y=26.8},{n="Hive'Zora Rubbing",a=1377,x=37.3,y=62.5},{n="Hive'Regal Rubbing",a=10073,x=44.4,y=86.1}}},
    [8310] = {l=60,ml=58,s={n="Frankal Stonebridge",a=1377,x=40.8,y=88.9},e={n="Frankal Stonebridge",a=1377,x=40.8,y=88.9},r={8304},o="Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.",st={{n="Hive'Ashi Silithid Brain",a=1377,x=44.4,y=21,m={"Hive'Ashi Swarmer","Hive'Ashi Defender","Hive'Ashi Stinger","Hive'Ashi Sandstalker"}},{n="Hive'Zora Silithid Brain",a=1377,x=25.4,y=63.2,m={"Hive'Zora Wasp","Hive'Zora Hive Sister","Hive'Zora Reaver","Hive'Zora Waywatcher"}},{n="Hive'Regal Silithid Brain",a=1377,x=58.1,y=80.2,m={"Hive'Regal Slavemaker","Hive'Regal Spitfire","Hive'Regal Hive Lord","Hive'Regal Ambusher"}}}},
    [8314] = {l=60,ml=58,s={n="Rutgar Glyphshaper",a=1377,x=41.3,y=88.5},e={n="Geologist Larksbane",a=1377,x=49.7,y=37.5},r={8309,8310},o="Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus."},
    [8315] = {l=60,ml=58,s={n="Geologist Larksbane",a=1377,x=49.7,y=37.5},e={n="Geologist Larksbane",a=1377,x=49.7,y=37.5},r={8314},o="Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.  You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.  Assemble an army for this task, <Name>!",st={{n="Crystal Unlocking Mechanism",a=1377,x=48.8,y=58.1,m={"Emissary Roman'khan"}}}},
    [8316] = {l=60,ml=58,s={n="Geologist Larksbane",a=1377,x=49.7,y=37.5},e={n="Geologist Larksbane",a=1377,x=49.7,y=37.5},r={8315}},
